 'collations',(select coalesce(jsonb_agg(to_jsonb(r)),'[]') from pg_catalog.pg_collation r),
 'casts',(select coalesce(jsonb_agg(to_jsonb(r)),'[]') from pg_catalog.pg_cast r),
 'eventTriggers',(select coalesce(jsonb_agg(to_jsonb(r)),'[]') from pg_catalog.pg_event_trigger r),
 'parameterACLs',(select coalesce(jsonb_agg(jsonb_build_object('oid',r."oid",'parname',r."parname")),'[]') from pg_catalog.pg_parameter_acl r),
 'enums',(select coalesce(jsonb_agg(to_jsonb(r)),'[]') from pg_catalog.pg_enum r),
 'acls',(select jsonb_agg(value) from (select jsonb_build_object('catalog','pg_namespace','object',r.oid,'sub',0,'isNull',r.nspacl is null,'entries',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from pg_catalog.aclexplode(case when cardinality(r.nspacl)>0 then r.nspacl else null end) x)) value from pg_catalog.pg_namespace r union all select jsonb_build_object('catalog','pg_class','object',r.oid,'sub',0,'isNull',r.relacl is null,'entries',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from pg_catalog.aclexplode(case when cardinality(r.relacl)>0 then r.relacl else null end) x)) value from pg_catalog.pg_class r union all select jsonb_build_object('catalog','pg_attribute','object',r.attrelid,'sub',r.attnum,'isNull',r.attacl is null,'entries',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from pg_catalog.aclexplode(case when cardinality(r.attacl)>0 then r.attacl else null end) x)) value from pg_catalog.pg_attribute r union all select jsonb_build_object('catalog','pg_proc','object',r.oid,'sub',0,'isNull',r.proacl is null,'entries',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from pg_catalog.aclexplode(case when cardinality(r.proacl)>0 then r.proacl else null end) x)) value from pg_catalog.pg_proc r union all select jsonb_build_object('catalog','pg_type','object',r.oid,'sub',0,'isNull',r.typacl is null,'entries',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from pg_catalog.aclexplode(case when cardinality(r.typacl)>0 then r.typacl else null end) x)) value from pg_catalog.pg_type r union all select jsonb_build_object('catalog','pg_language','object',r.oid,'sub',0,'isNull',r.lanacl is null,'entries',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from pg_catalog.aclexplode(case when cardinality(r.lanacl)>0 then r.lanacl else null end) x)) value from pg_catalog.pg_language r union all select jsonb_build_object('catalog','pg_default_acl','object',r.oid,'sub',0,'isNull',r.defaclacl is null,'entries',(select coalesce(jsonb_agg(to_jsonb(x)),'[]') from pg_catalog.aclexplode(case when